BEGIN;
CREATE TABLE IF NOT EXISTS referral_codes(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,code VARCHAR(32) NOT NULL UNIQUE CHECK(code ~ '^[A-Za-z0-9_-]{12,32}$'),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referral_attributions(id BIGSERIAL PRIMARY KEY,referred_user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,referrer_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,referral_code_id BIGINT NOT NULL REFERENCES referral_codes(id) ON DELETE RESTRICT,attributed_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL,CHECK(referred_user_id<>referrer_user_id));
CREATE TABLE IF NOT EXISTS commission_policies(id BIGSERIAL PRIMARY KEY,currency CHAR(3) NOT NULL UNIQUE CHECK(currency~'^[A-Z]{3}$'),basis_points INTEGER NOT NULL CHECK(basis_points BETWEEN 0 AND 5000),hold_days SMALLINT NOT NULL DEFAULT 14 CHECK(hold_days BETWEEN 0 AND 180),minimum_withdrawal_minor BIGINT NOT NULL CHECK(minimum_withdrawal_minor>0),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referral_rewards(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id) ON DELETE RESTRICT,referrer_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,referred_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,currency CHAR(3) NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),status VARCHAR(20) NOT NULL DEFAULT 'held' CHECK(status IN('held','available','reversed')),available_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reversed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS wallet_ledger(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,currency CHAR(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),amount_minor BIGINT NOT NULL CHECK(amount_minor<>0),entry_type VARCHAR(30) NOT NULL CHECK(entry_type IN('reward_credit','reward_reversal','withdrawal_reservation','withdrawal_release','payout')),reference_type VARCHAR(30) NOT NULL,reference_id BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(entry_type,reference_type,reference_id));
CREATE INDEX IF NOT EXISTS idx_wallet_user_currency ON wallet_ledger(user_id,currency,created_at,id);
CREATE TABLE IF NOT EXISTS withdrawal_requests(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,currency CHAR(3) NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','paid')),destination_ciphertext TEXT NOT NULL,destination_iv CHAR(24) NOT NULL,destination_tag CHAR(32) NOT NULL,destination_hint VARCHAR(80) NOT NULL,reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,review_note TEXT,requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ,paid_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_withdrawals_status ON withdrawal_requests(status,requested_at);
DROP TRIGGER IF EXISTS trg_commission_policy_updated_at ON commission_policies;CREATE TRIGGER trg_commission_policy_updated_at BEFORE UPDATE ON commission_policies FOR EACH ROW EXECUTE FUNCTION set_updated_at();
COMMIT;
